import React from 'react';
import './LibraryPage.css';

const moodColors = {
  happy: '#4CAF50',
  calm: '#2196F3',
  sad: '#9C27B0',
  energetic: '#FF9800',
  anxious: '#F44336',
  romantic: '#E91E63',
  angry: '#FF5722',
};

const mockPlaylists = [
  { playlistId: 1, title: 'Happy Vibes', mood: 'happy', createdAt: 'March 28, 2026', songCount: 18 },
  { playlistId: 2, title: 'Calm Evening', mood: 'calm', createdAt: 'March 25, 2026', songCount: 16 },
  { playlistId: 3, title: 'Workout Mix', mood: 'energetic', createdAt: 'March 22, 2026', songCount: 20 },
  { playlistId: 4, title: 'Rainy Day', mood: 'sad', createdAt: 'March 18, 2026', songCount: 15 },
];

function PlaylistCard({ playlist }) {
  const accentColor = moodColors[playlist.mood] || '#607D8B';

  return (
    <div className="playlist-card">
      <div className="card-accent" style={{ backgroundColor: accentColor }} />
      <div className="card-body">
        <h3 className="card-title">{playlist.title}</h3>
        <p className="card-meta">{playlist.createdAt} · {playlist.songCount} songs</p>
        <p className="card-mood">"{playlist.mood}"</p>
        <a href={`/playlist/${playlist.playlistId}`} className="card-link">View playlist →</a>
      </div>
    </div>
  );
}

function LibraryPage() {
  return (
  <div className="library-container">
  <div className="library-inner">
  <h1 className="library-title">My Library</h1>
  <p className="library-subtitle">Your saved playlists</p>
  <div className="library-grid">
        {mockPlaylists.map(p => (
          <PlaylistCard key={p.playlistId} playlist={p} />
        ))}
      </div>
    </div>
  </div>
  );
}

export default LibraryPage;
